
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _poolList: [],
        _freeType: 0,
        _storeEntranceStatus: false,//商店入口开关状态
        _goldIngotInfos: [],//所有下注对应的元宝信息 
    },


    init(deskInfo, gameId, gameJackpot) {
        this._super(deskInfo, gameId, gameJackpot);
        this._collect = this._deskInfo.collect;
        if (this._deskInfo.coinBonus) {
            this._poolList = this._deskInfo.coinBonus.poolList;
        }

        if (this._deskInfo.freeGameData) {
            this._freeType = this._deskInfo.freeGameData.freeType;
        }

        if(this._deskInfo.goldIngotInfoInFree){
            this.goldIngotInfoInFree = this._deskInfo.goldIngotInfoInFree;
        }
        this.SetJadeStore(this._deskInfo.jadeStore);
        this.SetGoldIngotInfos(this._deskInfo.goldIngotInfos);
    },

    onLoad() {

    },

    // overwrite
    OnRcvNetSpine: function (msg) {
        if (msg.code == 200) {
            // msg = {"select":true,"resultCards":[9,8,3,9,9,9,4,2,15,9,9,4,5,2,2],"code":200,"zjLuXian":[],"betcoin":10000,"wincoin":0,"lastBetCoin":3361522000,"subGameInfo":{"subGamid":-1,"isMustJoin":-1},"mults":[10000,20000,30000,50000,100000,150000],"coin":3361522000,"spLuXian":0,"allFreeCnt":0,"spcode":200,"bonusGame":{"open":0},"freeCnt":0,"pooljp":0,"scatterZJLuXian":{"mult":0,"coin":0,"indexs":[8,14,15]},"nextBetLine":{"spcode":500},"c":44,"spEffect":{"wincoin":0,"kind":0},"freeWinCoin":0,"addMult":1,"freeResult":{"freeInfo":{"idxs":[8,14,15],"scatter":2,"addMult":1,"freeCnt":0},"triFreeCnt":1}}

            // msg.resultCards=[12,6,6,6,7,12,6,6,6,13,6,10,6,11,6,6,10,7,11,6]
            // msg.zjLuXian=[{"mult":1,"coin":20000,"indexs":[11,7,3,9,15],"xlid":14,"card":6},{"mult":1,"coin":1000,"indexs":[11,7,8],"xlid":15,"card":6},{"mult":1,"coin":1000,"indexs":[11,7,13],"xlid":16,"card":6},{"mult":1,"coin":5000,"indexs":[11,7,3,9],"xlid":42,"card":6},{"mult":1,"coin":1000,"indexs":[11,7,8],"xlid":43,"card":6},{"mult":1,"coin":1000,"indexs":[11,7,13],"xlid":44,"card":6}]
            this._deskInfo.user.coin = msg.coin
            this._gameInfo = msg
            this._deskInfo.restFreeCount = msg.freeCnt
            this._deskInfo.allFreeCount = msg.allFreeCnt

            this._deskInfo.coinBonus = msg.coinBonus;

            this._needBet = this._deskInfo.needBet
            this.SetJadeStore(this._deskInfo.jadeStore)

            if(msg.goldIngotInfoInFree){
                this.goldIngotInfoInFree = msg.goldIngotInfoInFree;
            }
        }
        this._super(msg);
    },

    //set slotsNode
    SetSlotsNode(scp) {
        this._slotsNode = scp
    },

    //get slotsNode
    GetSlotsNode(scp) {
        return this._slotsNode
    },

    //商店脚本
    SetStoreScript(scp) {
        this._collectScp = scp;
    },
    GetStoreScript() {
        return this._collectScp;
    },

    //pop弹窗脚本
    SetPopScript(scp) {
        this._popupScp = scp;
    },
    GetPopScript() {
        return this._popupScp;
    },

    //免费游戏中转盘脚本
    SetWheelScript(scp) {
        this._wheelScp = scp;
    },
    GetWheelScript() {
        return this._wheelScp;
    },

    // 设置为空
    SetGoldIngotInfoInFree(val){
        this.goldIngotInfoInFree = val
    },
    GetGoldIngotInfoInFree(){
        return this.goldIngotInfoInFree
    },

    //不同下注对应的元宝排列信息
    SetGoldIngotInfos(goldIngotInfos) {
        this._goldIngotInfos = goldIngotInfos;
    },
    GetGoldIngotInfos() {
        return this._goldIngotInfos;
    },
    SetGoldIngotInfo(goldIngotInfo, index) {
        this._goldIngotInfos[index] = JSON.parse(JSON.stringify(goldIngotInfo));;
    },

    //获取开启商店入口下注
    GetOpenStoreBet() {
        let needBet = this._deskInfo.needBet || 1
        return this._deskInfo.mults[needBet - 1];
    },

    //获取商店信息
    GetJadeStore() {
        return this._jadeStore;
    },
    SetJadeStore(scp) {
        this._jadeStore = scp;
    },

    //商店入口按钮开关状态
    SetStoreEntranceStatus(scp) {
        this._storeEntranceStatus = scp;
    },
    GetStoreEntranceStatus() {
        return this._storeEntranceStatus;
    },

    //界面显示上 普通免费 和 商店开启的免费界面一样  单页免费卷轴不变黑
    //是否是处于免费游戏中  返回{status: true,times:10}   type: normal:普通免费 super:商店superwheel免费   pageReward:单页免费
    SetFreeGameTimes(_freeGameTimes) {
        this._freeGameTimes = _freeGameTimes;
    },
    GetFreeGameTimes() {
        return this._freeGameTimes;
    }
});