//鼠年转盘
let cfg = [2, 3, 4, 5, 6, 8, 10, 16, 20]

cc.Class({
    extends: cc.Component,

    properties: {
        _items: [],//item数组
        _itemWidth: 146,
        _slowSpeed: 30,//移动速度
        _fastSpeed: 90,//移动速度
    },

    Init() {

        for (let i = 0; i < 9; i++) {
            this._items.push(cc.find("moveNode/item" + i, this.node));
        }
    },

    onLoad() {

    },

    start() {

    },

    //转到指定的item
    moveToIndex() {
        
    },

    update(dt) {
        for (const iterator of this._items) {
            iterator.x += dt * this._slowSpeed;
            if (iterator.x >= 876) {
                iterator.x = -292
            }
        }

    }
});
