/**
 * -符号表
 */
const Hermes_Tools = require('./Hermes_Tools')

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _bonusIndex: 0,

        _data: null,
    },

    start() {

    },

    StartMove() {
        this._super();
        if (cc.vv.gameData.GetFreeGameTimes() && cc.vv.gameData.GetFreeGameTimes().status && cc.vv.gameData.GetFreeGameTimes().type != 'pageReward') {
            //免费游戏中 除了元宝以外的都展示黑底
            // if (this._id === 3 || this._id === 301 || this._id === 302 || this._id === 303 || this._id === 304) {
            //     // this.ShowMask(false)
            // } else {
            //     this.ShowMask(true)
            // }
            this.ShowMask(true)
        } else {
            this.ShowMask(false)
        }
    },

    hideOther() {
        cc.find('s3/lab', this.node).active = false
        cc.find('ingot', this.node).active = false
    },

    //显示symbole
    ShowById: function (id, data) {
        if (id === 20) {
            //空卷轴就随机
            id = Math.round(Math.random() * 5 + 4)
        }
        this._super(id, data);
        this.hideOther();
        this._data = data;
        if (data && data.type) {
            if (data.type === 1 && data.num) {  // 翡翠
                this.showIngot(data.num);
            }
            else if (data.type === 2 && data.item) {  // 元宝显示金币
                this.showWing(data.item)
            }
            else {
            }
        }
        //调整mask大小
        let mask = cc.find("mask", this.node)
        if (mask.active) {
            mask.height = this._showNode.height > 118 ? this._showNode.height : 118;
            if (this._id === 1) {
                //wild图标的宽度
                mask.width = 154
            } else {
                mask.width = this._showNode.width > 122 ? this._showNode.width : 122;
            }
        }
        // if (this._id === 3 || this._id === 301 || this._id === 302 || this._id === 303 || this._id === 304) {
        //     this.ShowMask(false)
        // }
        if (cc.vv.gameData.GetFreeGameTimes() && cc.vv.gameData.GetFreeGameTimes().status && cc.vv.gameData.GetFreeGameTimes().type != 'pageReward') {
            //免费游戏中 除了元宝以外的都展示黑底
            // if (this._id === 3 || this._id === 301 || this._id === 302 || this._id === 303 || this._id === 304) {
            //     // this.ShowMask(false)
            // } else {
            //     this.ShowMask(true)
            // }
            this.ShowMask(true)
        } else {
            this.ShowMask(false)
        }
    },

    showIngot(num) {
        let ingotNode = cc.find('ingot', this.node)
        ingotNode.active = true;
        cc.find('lab', ingotNode).getComponent(cc.Label).string = num
    },

    showWing(item) {
        if (item && item.coin) {
            let labNode = cc.find('s3/lab', this.node)
            labNode.active = true;
            labNode.getComponent(cc.Label).string = Global.formatNumShort(item.coin,0)
        }
    },

    //收集翡翠
    collectJade() {
        if (this._data && this._data.type === 1) {

            let targetNode = cc.find("Canvas/safe_node/slots/btn_collect/sd")
            let insIngotNode = cc.instantiate(cc.find('ingot', this.node))
            //let liziNode = cc.instantiate(cc.find('ingot/lizi', this.node))

            // insIngotNode.setPosition(cc.find('ingot', this.node).getPosition());
            //liziNode.parent = targetNode
            insIngotNode.parent = targetNode

            let pos1 = Hermes_Tools.convetOtherNodeSpace(cc.find('ingot', this.node), targetNode)
            // let pos2 = Hermes_Tools.convetOtherNodeSpace(this.node, targetNode)

            insIngotNode.setPosition(pos1);
            //liziNode.setPosition(pos1);

            cc.find('ingot', this.node).active = false;
            cc.tween(insIngotNode)
                .to(0.2, { scale: 1.7 })
                .to(0.5, { position: cc.v2(-60, 0) })
                .to(0.2, { opacity: 31, scale: 0.5})
                .call(() => {
                    insIngotNode.removeFromParent()
                })
                .start()

            // cc.tween(liziNode)
            //     .delay(0.2)
            //     .call(() => {
            //         liziNode.active = true;
            //     })
            //     .to(0.5, { position: cc.v2(0, 0) })
            //     .start()

        }
    },

    //获取元宝位置
    getIngotWPos() {
        return this.ingot().convertToWorldSpaceAR(cc.v2(0, 0));
    },

    //触发动画
    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playTriggerAnimation() {
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani) {
            this._state = "trigger";
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true
            if (cfg.symbol[id].trigger_ani.name != "") {
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if (nodeSp) {
                    nodeSp.setAnimation(0, cfg.symbol[id].trigger_ani.name, true)
                }
            }
        }
        return isPlay
    },

    //重写
    //在顶层播放动画；能覆盖左右两列
    setAnimationToTop(isTop) {
        if (this._topAniNode) {
            if (isTop) {
                let cloneNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s", this._symbolIdx, this._reelIdx), this._topAniNode);

                //如果有同一帧又创建了，需要判断卷轴是否有效
                if (!cloneNode) {
                    cloneNode = cc.instantiate(this.node)
                }

                let wordPos = this.node.convertToWorldSpaceAR(cc.v2(0.0));
                cloneNode.parent = this._topAniNode
                cloneNode.name = cc.js.formatStr("symbol_ani_%s_%s", this._symbolIdx, this._reelIdx)
                cloneNode.position = this._topAniNode.convertToNodeSpaceAR(wordPos)
                cc.find("ingot", cloneNode).removeFromParent()
                this.node.active = false
                return cloneNode
            } else {
                let showNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s", this._symbolIdx, this._reelIdx), this._topAniNode);
                if (showNode) {
                    //需要重复利用的话，隐藏就好
                    showNode.removeFromParent()
                    showNode.destroy()
                }
                this.node.active = true
                if (this._showNode) {
                    this._showNode.active = true
                }
            }
        }
        return this.node
    },

    playWinAnimation(){
        this.ShowMask(false);
        this._super()
    },

    //显示蒙板
    ShowMask(bShow) {
        // let mask = cc.find("mask", this.node)
        // mask.active = bShow

        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[this._id] && cfg.symbol[this._id].node){
            let showNode = cc.find(cfg.symbol[this._id].node,this.node)
            if (bShow/* && cfg.symbol[this._id].isMask*/) {
                showNode.color = new cc.Color(80, 80, 80);
                if(showNode.childrenCount > 0){
                    showNode.children.forEach(node=>{
                        node.color = new cc.Color(80, 80, 80);
                    })
                }
                // this.node.children.forEach(node=>{
                //     node.color = new cc.Color(80, 80, 80);
                // })
            }
            else {
                showNode.color = cc.Color.WHITE;
                if(showNode.childrenCount > 0){
                    showNode.children.forEach(node=>{
                        node.color = cc.Color.WHITE;
                    })
                }
                // this.node.children.forEach(node=>{
                //     node.color = cc.Color.WHITE;
                // })
            }
        }

    },
});
