//鼠年商店
const Hermes_Tools = require('./Hermes_Tools')

cc.Class({
    extends: cc.Component,

    properties: {
        _page: 1,//当前页数
        _pageState: 1,//当前页状态 1 未解锁 2 能解锁钱不够购买 3 能解锁钱足够购买 4 解锁完成当前页面 
        _boxes: [],      //箱子列表

        _layoutScale:1,
    },

    Init() {
        this._cannotOpenTip = cc.find("layout/view/cannotOpenTip", this.node);
        //箱子
        for (let i = 0; i < 9; i++) {
            let box = cc.find("layout/view/item" + (i + 1), this.node);
            box.on("click", this.onClickBoxBtn.bind(this));
            box.index = i;//第几个
            this._boxes[i] = {
                node: box,
                state: "canBuy", //open 已经打开 canBuy 能购买 lock 锁住
                type: 1,//类型 
                coin: null,//中奖金币
            };
        }
        cc.find("layout/view/zheZhao", this.node).active = false

        let layout = cc.find("layout", this.node);
        let curCanvas = cc.find('Canvas').getComponent(cc.Canvas);
        let scaleX = cc.winSize.width / curCanvas.designResolution.width;
        let scaleY = cc.winSize.height / curCanvas.designResolution.height;
        let min = Math.min(scaleX, scaleY);
        this._layoutScale = layout.scale * Math.min(min,1);
    },

    onLoad() {
        this._page = 1;

        let btn_close = cc.find('layout/btn_close', this.node)
        Global.btnClickEvent(btn_close, () => {
            this.openStore(false, true)
        }, this)
        //左滑动
        Global.btnClickEvent(cc.find("layout/btn_left", this.node), function () {
            Global.SlotsSoundMgr.playEffect("page");
            this.movePage(this._page - 1, 'left')
        }, this)
        //右滑动
        Global.btnClickEvent(cc.find("layout/btn_right", this.node), function () {
            Global.SlotsSoundMgr.playEffect("page");
            this.movePage(this._page + 1, 'right')
        }, this)
    },

    onEnable() {
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRecvMsgSubAction, this);
    },
    onDisable() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRecvMsgSubAction, false, this);
    },

    async onRecvMsgSubAction(msg) {
        if (msg.code === 200) {
            let data = msg.data;
            if (data.errMsg) return;

            let result = data.result;
            let slotsNode = cc.vv.gameData.GetSlotsNode()
            cc.vv.gameData.SetJadeStore(data.jadeStore)
            let unlockPage = data.jadeStore.unlockPage
            let nowPrice = data.jadeStore.pageDetails[this._page - 1].price;
            let jadeCnt = data.jadeStore.jadeCnt
            // idx = idx,
            // coin = 0, --获得的钱
            // type = GoldMouseType, --金鼠类型
            // freeInfo = nil, --如果是获得免费游戏，则有这个字段
            // pageReward = {  -- 当解锁了当前所有页，会有这个字段
            // freeCnt = pageDetail.freeCnt, --免费次数
            // convertCards = pageDetail.convertCards, --卷轴数量
            // wildMult = pageDetail.wildMult, --转换牌

            // result.idx 
            // result.coin 

            //刷新翡翠剩余数
            cc.vv.gameData.GetSlotsScript().refreshIngotUi(data.jadeStore.jadeCnt)

            let itemInfo = this._boxes[result.idx - 1];
            let item = this._boxes[result.idx - 1].node;
            let showNode = cc.find("open", item)
            let showSpine = null
            cc.find("open", item).active = false
            cc.find("lock", item).active = false
            cc.find("canBuy", item).active = false
            cc.find("open/coinLab", item).active = false
            itemInfo.state = 'open'

            if (result.type === 2) {
                //免费游戏
                showNode.active = true
                showSpine = showNode.getComponent(sp.Skeleton)

                showSpine.setAnimation(0, "animation2", false)
                showSpine.addAnimation(0, "animation2_1", false)
                cc.tween(slotsNode)
                    .delay(3)
                    .call(() => {
                        cc.vv.gameData.SetGoldIngotInfoInFree(result.goldIngotInfoInFree);
                        cc.vv.gameData.SetFreeGameTimes({ status: true, times: result.freeInfo.freeCnt, type: "normal" })
                        this.openStore(false)
                        cc.find("layout/view/zheZhao", this.node).active = false
                    })
                    .delay(0.5)
                    .call(() => {
                        cc.vv.gameData.GetSlotsScript().CheckEnterFreeGame(result.freeInfo.freeCnt)
                    })
                    .start()
            } else if (result.type === 3) {
                //super免费游戏
                showNode.active = true
                showSpine = showNode.getComponent(sp.Skeleton)

                showSpine.setAnimation(0, "animation3", false)
                showSpine.addAnimation(0, "animation3_1", false)
                cc.tween(slotsNode)
                    .delay(3)
                    .call(() => {
                        cc.vv.gameData.SetGoldIngotInfoInFree(result.goldIngotInfoInFree);
                        cc.vv.gameData.SetFreeGameTimes({ status: true, times: result.freeInfo.freeCnt, type: "super" })
                        this.openStore(false)
                        cc.find("layout/view/zheZhao", this.node).active = false
                    })
                    .delay(0.5)
                    .call(() => {
                        cc.vv.gameData.GetSlotsScript().CheckEnterFreeGame(result.freeInfo.freeCnt)
                    })
                    .start()
            } else if (result.type === 1) {
                //金币
                showNode.active = true
                showSpine = showNode.getComponent(sp.Skeleton)

                showSpine.setAnimation(0, "animation1", false)
                showSpine.addAnimation(0, "animation1_1", false)
                //显示中奖的金币
                let haveWin = cc.vv.gameData.GetBottomScript().getCurrentWin()
                let addCoin = result.coin
                cc.vv.gameData.AddCoin(addCoin)
                cc.vv.gameData.GetBottomScript().ShowWin(addCoin + haveWin, 3, haveWin, null, 0.3)
                cc.vv.gameData.GetTopScript().ShowCoin()

                cc.tween(slotsNode)
                    .delay(1)
                    .call(() => {
                        cc.find("open/coinLab", item).active = true
                        cc.find("open/coinLab", item).getComponent(cc.Label).string = Global.formatNumShort(result.coin, 0)
                        cc.find("layout/view/zheZhao", this.node).active = false
                    })
                    .start()
            }

            //刷新数据
            if (this._page <= unlockPage) {
                //碎片不足购买
                if (jadeCnt < nowPrice) {
                    for (const iterator of this._boxes) {
                        if (iterator.state == 'canBuy') {
                            iterator.state = 'canNotBuy'
                        }
                    }
                }
            }

            if (result.pageReward) {
                //单页奖励
                Global.SlotsSoundMgr.playEffect("logo_store");
                cc.tween(slotsNode)
                    .delay(2)
                    .call(() => {
                        this.playUpSymbolAni('open')
                    })
                    .delay(3)
                    .call(() => {
                        this.openStore(false)
                        cc.find("layout/view/zheZhao", this.node).active = false
                    })
                    .delay(0.5)
                    .call(() => {
                        cc.vv.gameData.SetFreeGameTimes({ status: true, times: result.pageReward.freeCnt, type: "pageReward", page: this._page })
                        cc.vv.gameData.GetSlotsScript().CheckEnterFreeGame(result.pageReward.freeCnt)
                    })
                    .start()
            }

        }
    },

    //打开商店
    openStore(isOpen, CanDoNextRound) {
        let store_bg = cc.find("store_bg", this.node)
        let layout = cc.find("layout", this.node)
        cc.find("layout/view/zheZhao", this.node).active = false

        if (isOpen) {
            this.node.active = isOpen
            store_bg.active = isOpen
            layout.active = isOpen
            store_bg.opacity = 0
            layout.scale = 0

            Global.SlotsSoundMgr.playEffect("popup_out");
            cc.tween(layout)
                .to(0.5, { scale: this._layoutScale })
                .start()
            cc.tween(store_bg)
                .to(0.5, { opacity: 255 })
                .start()

            this.movePage(this._page)
            this.updateUi();
        } else {
            Global.SlotsSoundMgr.playEffect("close");

            cc.tween(layout)
                .to(0.5, { scale: 0 })
                .call(() => {
                    this.node.active = isOpen
                })
                .start()
            cc.tween(store_bg)
                .to(0.5, { opacity: 0 })
                .start()
            if (CanDoNextRound) {
                cc.vv.gameData.GetSlotsScript().CanDoNextRound();
            }
        }

    },

    //更新界面ui
    updateUi() {
        let jadeStore = cc.vv.gameData.GetJadeStore()
        let unlockPage = jadeStore.unlockPage
        let unlockItems = jadeStore.unlockItems
        let nowPrice = jadeStore.pageDetails[this._page - 1].price;
        let jadeCnt = jadeStore.jadeCnt

        cc.vv.gameData.GetSlotsScript().refreshIngotUi(jadeStore.jadeCnt)
        //刷新数据
        if (this._page <= unlockPage) {
            //当前页面已经解锁
            let isCanBuyState = "canBuy"
            if (jadeCnt < nowPrice) {
                isCanBuyState = "canNotBuy"
            }
            for (const iterator of this._boxes) {
                iterator.state = isCanBuyState
            }
            for (const iterator of unlockItems[this._page - 1]) {
                this._boxes[iterator.idx - 1].state = 'open'
                this._boxes[iterator.idx - 1].type = iterator.type
                this._boxes[iterator.idx - 1].coin = iterator.coin
            }
        } else {
            //当前页面未解锁
            for (const iterator of this._boxes) {
                iterator.state = 'lock'
            }
        }
        //刷新界面
        for (let i = 0; i < 9; i++) {
            let itemNode = cc.find("layout/view/item" + (i + 1), this.node)
            let itemInfo = this._boxes[i]
            cc.find("lock", itemNode).active = false
            cc.find("open", itemNode).active = false
            cc.find("canBuy", itemNode).active = false

            if (itemInfo.state == 'lock') {
                cc.find("lock", itemNode).active = true
                cc.find("lock", itemNode).getComponent(sp.Skeleton).setAnimation(0, "animation2", false)
                cc.find("lock/priceNode/lab", itemNode).getComponent(cc.Label).string = Global.FormatNumToComma(nowPrice)
            } else if (itemInfo.state == 'open') {
                cc.find("open", itemNode).active = true
                switch (itemInfo.type) {
                    case 1:
                        // 金币
                        cc.find("open/coinLab", itemNode).active = true
                        cc.find("open", itemNode).getComponent(sp.Skeleton).setAnimation(0, "animation1_1", false)
                        cc.find("open/coinLab", itemNode).getComponent(cc.Label).string = Global.formatNumShort(itemInfo.coin, 0)
                        break;
                    case 2:
                        //免费游戏
                        cc.find("open/coinLab", itemNode).active = false
                        cc.find("open", itemNode).getComponent(sp.Skeleton).setAnimation(0, "animation2_1", false)
                        break;
                    case 3:
                        //超级免费游戏
                        cc.find("open/coinLab", itemNode).active = false
                        cc.find("open", itemNode).getComponent(sp.Skeleton).setAnimation(0, "animation3_1", false)
                        break;
                    default:
                        break;
                }
            } else if (itemInfo.state == 'canBuy') {
                cc.find("canBuy", itemNode).active = true
                cc.find("canBuy/priceNode/lab", itemNode).getComponent(cc.Label).string = Global.FormatNumToComma(nowPrice)
                let canBuySpineCom = cc.find("canBuy", itemNode).getComponent(sp.Skeleton)
                canBuySpineCom.setAnimation(0, "animation3", false)
            } else if (itemInfo.state == 'canNotBuy') {
                cc.find("canBuy", itemNode).active = true
                cc.find("canBuy/priceNode/lab", itemNode).getComponent(cc.Label).string = Global.FormatNumToComma(nowPrice)
                let canBuySpineCom = cc.find("canBuy", itemNode).getComponent(sp.Skeleton)
                canBuySpineCom.setAnimation(0, "animation1", false)
            }
        }
    },

    //移动页面 page :页数 type:翻页方向
    movePage(page, type) {
        let self = this;
        let gameData = cc.vv.gameData
        let jadeStore = gameData.GetJadeStore()
        let unlockPage = jadeStore.unlockPage
        Global.SlotsSoundMgr.playEffect("page");

        if (page <= 0) {
            page = 4
        } else if (page >= 5) {
            page = 1
        }
        this._page = page
        this.updateUi();

        //商店上方spine
        if (this._page >= unlockPage) {
            //到未解锁页面
            this.playUpSymbolAni("close")
        } else {
            //到已解锁页面
            this.playUpSymbolAni("hasOpen")
        }

        //上方文字动画
        let upSpine = cc.find("layout/upBg/shangdian", this.node).getComponent(sp.Skeleton)
        let track = upSpine.setAnimation(0, 'animation' + this._page, false)
        Hermes_Tools.spineEndFunc(cc.find("layout/upBg/shangdian", this.node), track, () => {
            upSpine.setAnimation(0, 'animation' + self._page + "_1", false)
        })
        //下方页面显示
        let choose_bg = cc.find("layout/choose_bg", this.node)
        for (const iterator of choose_bg.children) {
            cc.find("choosed", iterator).active = false
            if (iterator.name.slice(6) == this._page) {
                cc.find("choosed", iterator).active = true
            }
        }
        //节点动画
        if (!type) return;
        let movePosx = 100
        if (type === 'right') {
            movePosx = -100
        }
        for (let i = 0; i < 9; i++) {
            let itemNode = cc.find("layout/view/item" + (i + 1), this.node)
            let posX = itemNode.x
            cc.tween(itemNode)
                .to(0.2, { opacity: 0, x: posX + movePosx })
                .to(0.01, { x: posX, scale: 0, opacity: 360 })
                .delay(i * 0.03)
                .to(0.2, { scale: 1 })
                .start()
        }
    },

    //上方symbol动画
    playUpSymbolAni(status) {
        let upSymbolSpine = cc.find("layout/upBg/chuxian", this.node).getComponent(sp.Skeleton)
        let page = this._page
        if (status === "hasOpen") {
            upSymbolSpine.setAnimation(0, 'animation' + page + "_1", false)

        } else if (status === "open") {
            upSymbolSpine.setAnimation(0, 'animation' + page, false)
            upSymbolSpine.addAnimation(0, 'animation' + page + "_1", false)

        } else if (status === "close") {
            upSymbolSpine.setAnimation(0, 'animation' + page + "_2", false)

        }

    },

    onClickBoxBtn(event) {
        let index = event.node.index;
        let jadeStore = cc.vv.gameData.GetJadeStore()
        let nowPrice = jadeStore.pageDetails[this._page - 1].price;
        let jadeCnt = jadeStore.jadeCnt;

        if (jadeCnt < nowPrice && this._boxes[index].state === "canNotBuy") {
            //钱不够
            Global.SlotsSoundMgr.playEffect("nomoney");

            let tipNode = this._cannotOpenTip
            tipNode.stopAllActions()
            tipNode.x = event.node.x
            tipNode.y = event.node.y
            tipNode.active = true
            tipNode.scale = 0
            cc.tween(tipNode)
                .to(0.5, { scale: 1 })
                .delay(0.3)
                .call(() => {
                    tipNode.active = false
                })
                .start()
            return
        }

        if (this._boxes[index].state === "canBuy") {
            Global.SlotsSoundMgr.playEffect("buy");
            // 发送51消息
            let req = { c: MsgId.SLOT_SUBGAME_DATA };
            req.gameid = cc.vv.gameData.getGameId()
            req.data = {}
            req.data.rtype = 1
            req.data.pageId = this._page
            req.data.choiceId = index + 1
            cc.vv.NetManager.send(req, true);
            cc.find("layout/view/zheZhao", this.node).active = true
        } else {

        }
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

});
