/**
 * 卷轴控制单元
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _reelIdx: null,
        _coin: 0,//足列元宝金币数值
        _count: 0,  //卷轴的symbol个数
        _symbols: [],    //符号脚本对象。需要获得节点对象则：this._symbols[i].node
        _col: 5,
        _row: 8,
        _items: null,//单列数据保存
        _idxs: null,//单列数据保存
        _restCnt: null,//单列数据保存

        _yellowKuang: null,//黄色框动画数组
    },

    //初始化卷轴
    //idx:卷轴序号(列序号)，0开始
    //nCount:符号个数
    Init: function (_reelIdx) {
        let dataArr = [4, 4, 6, 6, 8]
        this._reelIdx = _reelIdx
        this._count = dataArr[_reelIdx]
        this._coin = 0;
    },

    //获取当前的reelIdx
    GetReelIdx: function () {
        return this._reelIdx
    },

    //设置一列的banous 图标 isInitWing:是否是初始化元宝显示
    SetBonusReel(idxs, items, restCnt, fullCnt, isInitWing) {
        this._idxs = idxs
        this._items = items
        this._restCnt = restCnt
        this._fullCnt = fullCnt
        let gameData = cc.vv.gameData
        let holderNode = cc.find("mask/holder", this.node)

        if (gameData.GetFreeGameTimes() && gameData.GetFreeGameTimes().status == true) {
            //免费游戏中
        } else {
            //普通游戏中
            this.showSmallWing()
        }

        for (let i = 0; i < this._count; i++) {
            let bonus_Symbol = cc.find("bonus_Symbol" + i, holderNode)
            bonus_Symbol.check = false
            bonus_Symbol.active = false
        }
        let index = 0
        let play_bonus_notify = false
        let m = []
        if (Array.isArray(idxs)) { m = idxs}
        for (const idx of m/*idxs*/) {
            //所在行列数 0开始
            let col = (idx - 1) % this._col
            let row = this._row - Math.floor((idx - 1) / this._col) - 1
            let bonus_Symbol = cc.find("bonus_Symbol" + row, holderNode)
            if (!bonus_Symbol.check && !isInitWing) {
                // if(!cc.vv.gameData.GetFreeGameTimes().status){
                play_bonus_notify = true
                // }
            }
            bonus_Symbol.active = true
            bonus_Symbol.check = true
            //check 用于检查是否是新图标
            let bs = []
            if (Array.isArray(bonus_Symbol.children)) { bs = bonus_Symbol.children }
            for (const iterator of bs/*bonus_Symbol.children*/) {
                iterator.check = false
                iterator.active = false
            }
            let itemInfo = items[index]
            index++;
            if (itemInfo.coin) {
                cc.find("s3/lab", bonus_Symbol).getComponent(cc.Label).string = Global.formatNumShort(itemInfo.coin,0);
                cc.find("s3", bonus_Symbol).active = true
            } else if (itemInfo.jackpotId == 1) {
                cc.find("s301", bonus_Symbol).active = true
            } else if (itemInfo.jackpotId == 2) {
                cc.find("s302", bonus_Symbol).active = true
            } else if (itemInfo.jackpotId == 3) {
                cc.find("s303", bonus_Symbol).active = true
            } else if (itemInfo.jackpotId == 4) {
                cc.find("s304", bonus_Symbol).active = true
            }

        }

        if (play_bonus_notify) {
            // sfx 替换  bonus_notify -> jewelDown
            // 所以这个代码就尴尬了
            Global.SlotsSoundMgr.playEffect("bonus_notify");
        }

        this.showKuang()
    },

    //展示边框特效
    showKuang() {
        let idxs = this._idxs;
        let self = this
        //只差一个满足
        if ((this._fullCnt - 1) === idxs.length) {
            //单个蓝色图标
            if (!cc.find("mask/spine_blue", this.node).active) {
                let aniNameArr = ['animation4_', 'animation4_', 'animation6_', 'animation6_', 'animation8_']
                let spine = cc.find("mask/spine_blue", this.node).getComponent(sp.Skeleton)
                cc.find("mask/spine_blue", this.node).active = true;
                spine.setAnimation(0, aniNameArr[this._reelIdx] + 1, false)
                spine.setCompleteListener((track) => {
                    spine.setAnimation(0, aniNameArr[self._reelIdx] + 2, false)
                });
                return;
            }
        } else {
            cc.find("mask/spine_blue", this.node).active = false;

        }

        let rowArr = []
        let ti = []
        if (Array.isArray(idxs)) { ti = idxs}
        for (const idx of ti/*idxs*/) {
            //所在行列数 0开始
            let col = (idx - 1) % this._col;
            let row = this._row - Math.floor((idx - 1) / this._col) - 1;
            rowArr.push(row);
        }
        rowArr.sort();
    },

    //卷轴开始转
    StartMove() {
        let idxs = this._idxs;

        if (this._restCnt>=0 && idxs && (this._fullCnt - 1) === idxs.length) {   
            //单个蓝色图标
            let dataArr = [{ index: 0, check: false, y: 46.5 }, { index: 1, check: false, y: 139.5 }, { index: 2, check: false, y: 232.5 }, { index: 3, check: false, y: 325.5 }, { index: 4, check: false, y: 418.5 }, { index: 5, check: false, y: 511.5 }, { index: 6, check: false, y: 604.5 }, { index: 7, check: false, y: 697.5 }]
            let indexObj = {}
            let ti = []
            if (Array.isArray(idxs)) { ti = idxs }
            for (const idx of ti/*idxs*/) {
                //所在行列数 0开始
                let col = (idx - 1) % this._col;
                let row = this._row - Math.floor((idx - 1) / this._col) - 1;
                dataArr[row].check = true
            }
            let da = []
            if (Array.isArray(dataArr)) { da = dataArr }
            for (const iterator of da/*dataArr*/) {
                if (iterator.check == false) {
                    indexObj = iterator
                    break;
                }
            }
            cc.find("mask/spine_one_blue", this.node).active = true
            cc.find("mask/spine_one_blue", this.node).getComponent(sp.Skeleton).setAnimation(0, "animation", true)
            cc.find("mask/spine_one_blue", this.node).y = indexObj.y
        } else {
            cc.find("mask/spine_one_blue", this.node).active = false
            cc.find("mask/spine_blue", this.node).active = false

        }
    },

    //旋转停止
    OnSpinEnd() {
        cc.find("mask/spine_one_blue", this.node).active = false
        if(this._restCnt<=0){
            cc.find("mask/spine_blue", this.node).active = false
        }
    },

    //是否满了一竖列 收集元宝
    async collectWing(reelGoldIngotInfo) {
        let self = this;
        let slotsNode = cc.vv.gameData.GetSlotsNode()
        let holderNode = cc.find("mask/holder", this.node)
        let str = "reels_frame/lint_bottom/down/coin" + (this._reelIdx + 1) + "/lab"
        this._coin = 0;
        cc.find(str, slotsNode).getComponent(cc.Label).string = this._coin;

        if (reelGoldIngotInfo.length > 0) {
            let aniNameArr = ['animation4_', 'animation4_', 'animation6_', 'animation6_', 'animation8_']
            let spine = cc.find("mask/spine_purple", this.node).getComponent(sp.Skeleton)
            cc.find("mask/spine_purple", this.node).active = true;
            cc.find("mask/spine_blue", this.node).active = false;
            cc.find("mask/spine_one_blue", this.node).active = false

            spine.setAnimation(0, aniNameArr[this._reelIdx] + 1, false)
            spine.setCompleteListener((track) => {
                spine.setAnimation(0, aniNameArr[self._reelIdx] + 2, false)
            });
            Global.SlotsSoundMgr.playEffect("appear");
            await this.awaitTime(2)
            let firstPosArr = []
            let jptime = 0 //有几个jp 每个jp大奖动画展示时间4s
            for (let key in reelGoldIngotInfo) {
                let itemInfo = reelGoldIngotInfo[key]
                //所在行列数 0开始
                let col = (itemInfo.idx - 1) % this._col
                let row = this._row - Math.floor((itemInfo.idx - 1) / this._col) - 1
                let bonus_Symbol = cc.find("bonus_Symbol" + row, holderNode)
                bonus_Symbol.active = true
                firstPosArr.push(bonus_Symbol.y)
                let str = "reels_frame/lint_bottom/down/coin" + (col + 1)
                let str2 = "reels_frame/lint_bottom/down/item" + (col + 1)
                let coinNode = cc.find(str, slotsNode)
                let stoveNode = cc.find(str2, slotsNode)
                let coinLabNode = cc.find("lab", coinNode)
                coinNode.active = true;
                let delayTime = key
                cc.tween(bonus_Symbol)
                    .by(0.2, { y: 10 })
                    .delay(delayTime * 1 + jptime)
                    .call(() => {
                        Global.SlotsSoundMgr.playEffect("jubaopen");
                    })
                    .to(0.6, { y: -76 })
                    .call(() => {
                        bonus_Symbol.y = firstPosArr[delayTime]
                        if (itemInfo.item.jackpotValue) {
                            this._coin += itemInfo.item.jackpotValue;
                        }
                        if (itemInfo.item.coin) this._coin += itemInfo.item.coin;
                        coinLabNode.getComponent(cc.Label).string = Global.formatNumShort(this._coin, 0);
                        cc.find("spineShan", stoveNode).active = true
                        cc.find("spineShan", stoveNode).getComponent(sp.Skeleton).setAnimation(0, "animation", false)
                        bonus_Symbol.active = false
                        if(itemInfo.item.jackpotId){
                            cc.vv.gameData.GetSlotsScript().showJpDialog(itemInfo.item.jackpotId)
                        }

                        if (delayTime == (reelGoldIngotInfo.length - 1)) {
                            //最后一个
                            cc.tween(slotsNode)
                                .delay(0.8)
                                .call(() => {
                                    cc.find("spineShan", stoveNode).active = false
                                    cc.find("mask/spine_purple", this.node).active = false;
                                })
                                .start()
                        }
                    })
                    .start()
                if (itemInfo.item.jackpotValue) {
                    jptime += 4
                }
            }
            await this.awaitTime(reelGoldIngotInfo.length * 1.2 + 2 + jptime)

        } else {
            cc.find("mask/spine_purple", this.node).active = false;
        }
    },

    //下方小元宝显示 type:1 元宝数减1
    showSmallWing(type) {
        let slotsNode = cc.vv.gameData.GetSlotsNode()
        let holderNode = cc.find("mask/holder", this.node)
        let itemNode = cc.find("reels_frame/lint_bottom/down/item" + (this._reelIdx + 1), slotsNode)
        let upbgNode = cc.find("mask/upBg", itemNode)

        if (this._restCnt <= 0) {
            // 无
            cc.tween(upbgNode)
                .to(0.2, { y: 45 })
                .start()
            for (const iterator of holderNode.children) {
                iterator.active = false;
            }
        } else {
            cc.tween(upbgNode)
                .to(0.2, { y: 0 })
                .start()
        }

        if (type === 1) {
            this._restCnt -= 1;
        }

        let idxs = this._idxs
        if (Array.isArray(idxs) && idxs.length > 0) {
            let wingNodeArr = [cc.find('wing1', upbgNode), cc.find('wing2', upbgNode), cc.find('wing3', upbgNode)]
            for (let i = 0; i < 3; i++) {
                wingNodeArr[i].active = i < this._restCnt
            }

        }
    },

    //隐藏上方悬浮元宝
    hideSuspendWing() {
        for (let i = 0; i < this._count; i++) {
            cc.find("mask/holder/bonus_Symbol" + i, this.node).active = false
        }
    },

    //隐藏所有框
    hideAllKuang() {
        cc.find("mask/spine_purple", this.node).active = false;
        cc.find("mask/spine_blue", this.node).active = false;
        cc.find("mask/spine_one_blue", this.node).active = false
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    }
});
