cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    //初始化公共组件
    InitCommComponent: function () {
        this._super();

        cc.vv.gameData.SetSlotsNode(cc.vv.gameData.GetSlotsScript().node)
        //资源加载脚本
        let Hermes_Store = cc.find("safe_node/node_store", this.node).addComponent("Hermes_Store")
        Hermes_Store.Init()
        cc.vv.gameData.SetStoreScript(Hermes_Store)
        //免费游戏转盘脚本
        let wheelNode = cc.find("safe_node/freeGame/zhuanPanNode", this.node)
        let script_wheel = wheelNode.addComponent("Hermes_Wheel")
        script_wheel.Init()
        cc.vv.gameData.SetWheelScript(script_wheel);

        // let script_bonus = this.node.addComponent("Hermes_BonusGame")
        // script_bonus.Init()
        // cc.vv.gameData.SetBonusScript(script_bonus);

    },

});
